<script data-page="app" type="application/json">{"component":"sentence-trainer\/index","props":{"errors":{},"name":"TopEwords","auth":{"user":{"id":2,"name":"Szaniszl\u00f3 \u00c1rp\u00e1d","email":"developedbybarley@gmail.com","email_verified_at":null,"two_factor_confirmed_at":null,"streak":1,"quiz_completions":0,"text_analyses":3,"last_activity_date":"2026-04-24T00:00:00.000000Z","onboarding_completed_at":"2026-04-30T14:18:38.000000Z","created_at":"2026-04-09T16:08:47.000000Z","updated_at":"2026-05-01T12:59:41.000000Z","stripe_id":"cus_UR8xKFxwoTTbBR","pm_type":null,"pm_last_four":null,"trial_ends_at":null,"ai_access":false,"free_usage":null,"ai_usage_usd":"0.0000","ai_usage_period":null,"subscriptions":[]},"isAdmin":true,"subscription":{"hasActiveAccess":true,"isSubscribed":false,"isPremium":false,"hasAiAccess":false,"isOnTrial":false}},"sidebarOpen":true,"flash":{"streakTriggered":null,"success":null,"achievements":[],"calibrationPrompt":null,"showTour":false,"importedCardId":null},"sentences":[{"id":1,"category":"would_have","english":"It <b>would have meant<\/b> a lot to her.","hungarian":"Sokat jelentett volna neki.","explanation":"<b>would have + past participle<\/b> \u2014 felt\u00e9teles m\u00falt. Valami megt\u00f6rt\u00e9nhetett volna, de nem t\u00f6rt\u00e9nt meg."},{"id":2,"category":"would_have","english":"He <b>would have told<\/b> you if he knew.","hungarian":"Mondta volna neked, ha tudta volna.","explanation":"<b>would have + past participle<\/b> \u2014 3. felt\u00e9teles, m\u00faltbeli hipotetikus helyzet."},{"id":3,"category":"would_have","english":"They <b>would have arrived<\/b> earlier without the traffic.","hungarian":"Hamarabb \u00e9rkeztek volna, ha nincs dug\u00f3.","explanation":"<b>would have + past participle<\/b> \u2014 a k\u00f6zleked\u00e9si dug\u00f3 megakad\u00e1lyozta a kor\u00e1bbi \u00e9rkez\u00e9st."},{"id":4,"category":"would_have","english":"I <b>would have called<\/b> you, but my phone died.","hungarian":"Felh\u00edvtalak volna, de lemer\u00fclt a telefonom.","explanation":"<b>would have + past participle<\/b> \u2014 sz\u00e1nd\u00e9k volt, de valami megakad\u00e1lyozta."},{"id":5,"category":"could_have","english":"You <b>could have told<\/b> me earlier.","hungarian":"Kor\u00e1bban is megmondhattad volna nekem.","explanation":"<b>could have + past participle<\/b> \u2014 lehet\u0151s\u00e9g volt r\u00e1, de nem \u00e9lt vele. Szemreh\u00e1ny\u00e1s \u00e1rnyalat\u00e1val."},{"id":6,"category":"could_have","english":"She <b>could have been<\/b> a professional dancer.","hungarian":"Hivat\u00e1sos t\u00e1ncos is lehetett volna bel\u0151le.","explanation":"<b>could have + past participle<\/b> \u2014 m\u00faltbeli lehet\u0151s\u00e9g, ami nem val\u00f3sult meg."},{"id":7,"category":"could_have","english":"We <b>could have avoided<\/b> the whole problem.","hungarian":"Eg\u00e9sz probl\u00e9m\u00e1t el lehetett volna ker\u00fclni.","explanation":"<b>could have + past participle<\/b> \u2014 elmulasztott lehet\u0151s\u00e9g."},{"id":8,"category":"should_have","english":"I <b>should have listened<\/b> to your advice.","hungarian":"Hallgatnom kellett volna a tan\u00e1csodra.","explanation":"<b>should have + past participle<\/b> \u2014 ut\u00f3lagos sajn\u00e1lat, valamit elmulasztottunk megtenni."},{"id":9,"category":"should_have","english":"You <b>should have booked<\/b> the tickets in advance.","hungarian":"El\u0151re kellett volna foglalni a jegyeket.","explanation":"<b>should have + past participle<\/b> \u2014 szemreh\u00e1ny\u00e1s vagy tan\u00e1cs ut\u00f3lag."},{"id":10,"category":"should_have","english":"He <b>should have known<\/b> better.","hungarian":"Jobban kellett volna tudnia.","explanation":"<b>should have + past participle<\/b> \u2014 elv\u00e1r\u00e1s, amit nem teljes\u00edtett valaki."},{"id":11,"category":"might_have","english":"She <b>might have forgotten<\/b> about the meeting.","hungarian":"Lehet, hogy elfelejtette az \u00e9rtekezletet.","explanation":"<b>might have + past participle<\/b> \u2014 bizonytalan m\u00faltbeli k\u00f6vetkeztet\u00e9s, gyenge val\u00f3sz\u00edn\u0171s\u00e9g."},{"id":12,"category":"might_have","english":"They <b>might have left<\/b> already.","hungarian":"Lehet, hogy m\u00e1r elmentek.","explanation":"<b>might have + past participle<\/b> \u2014 nem bizonyos, de lehets\u00e9ges."},{"id":13,"category":"might_have","english":"It <b>might have been<\/b> a misunderstanding.","hungarian":"Lehet, hogy f\u00e9lre\u00e9rt\u00e9s volt.","explanation":"<b>might have + past participle<\/b> \u2014 visszatekint\u0151 spekul\u00e1ci\u00f3."},{"id":14,"category":"must_have","english":"It <b>must have been<\/b> a mistake.","hungarian":"Biztosan hiba volt.","explanation":"<b>must have + past participle<\/b> \u2014 er\u0151s logikai k\u00f6vetkeztet\u00e9s m\u00falt id\u0151re."},{"id":15,"category":"must_have","english":"She <b>must have worked<\/b> very hard to pass that exam.","hungarian":"Nagyon kem\u00e9nyen dolgozhatott, hogy \u00e1tmenjen azon a vizsg\u00e1n.","explanation":"<b>must have + past participle<\/b> \u2014 logikus k\u00f6vetkeztet\u00e9s bizony\u00edt\u00e9kok alapj\u00e1n."},{"id":16,"category":"must_have","english":"You <b>must have misunderstood<\/b> what I said.","hungarian":"Biztosan f\u00e9lre\u00e9rtetted, amit mondtam.","explanation":"<b>must have + past participle<\/b> \u2014 meggy\u0151z\u0151d\u00e9s a m\u00faltbeli esem\u00e9nyr\u0151l."},{"id":17,"category":"have_been","english":"It <b>has been considered<\/b> a classic for decades.","hungarian":"\u00c9vtizedek \u00f3ta klasszikusnak tartj\u00e1k.","explanation":"<b>has been considered<\/b> \u2014 present perfect passive. M\u00faltban kezd\u0151d\u00f6tt, m\u00e1ig \u00e9rv\u00e9nyes."},{"id":18,"category":"have_been","english":"She <b>has been thinking<\/b> about changing her career.","hungarian":"Egy ideje azon gondolkodik, hogy p\u00e1ly\u00e1t v\u00e1ltoztat.","explanation":"<b>has been thinking<\/b> \u2014 present perfect continuous. Elkezd\u0151d\u00f6tt, \u00e9s m\u00e9g tart."},{"id":19,"category":"have_been","english":"They <b>have been married<\/b> for twenty years.","hungarian":"H\u00fasz \u00e9ve h\u00e1zasok.","explanation":"<b>have been + past participle\/adjective<\/b> \u2014 m\u00faltban kezd\u0151d\u00f6tt \u00e1llapot, amely m\u00e1ig tart."},{"id":20,"category":"have_been","english":"The company <b>has been growing<\/b> steadily since 2010.","hungarian":"A c\u00e9g 2010 \u00f3ta folyamatosan n\u00f6vekszik.","explanation":"<b>has been growing<\/b> \u2014 present perfect continuous, folyamatos, lez\u00e1ratlan cselekv\u00e9s."},{"id":21,"category":"passive","english":"The letter <b>was being written<\/b> when she called.","hungarian":"A lev\u00e9l \u00e9pp \u00edr\u00f3dott, amikor felh\u00edvott.","explanation":"<b>was being written<\/b> \u2014 past continuous passive. Folyamatban l\u00e9v\u0151 cselekv\u00e9s a m\u00faltban."},{"id":22,"category":"passive","english":"The bridge <b>will be completed<\/b> next year.","hungarian":"A hidat j\u00f6v\u0151re fejezik be.","explanation":"<b>will be + past participle<\/b> \u2014 j\u00f6v\u0151 id\u0151 passive. Ki fogja elv\u00e9gezni, nem fontos."},{"id":23,"category":"passive","english":"The new policy <b>has been introduced<\/b> to reduce costs.","hungarian":"Az \u00faj szab\u00e1lyzatot a k\u00f6lts\u00e9gek cs\u00f6kkent\u00e9se \u00e9rdek\u00e9ben vezett\u00e9k be.","explanation":"<b>has been introduced<\/b> \u2014 present perfect passive. A bevezet\u00e9s megt\u00f6rt\u00e9nt, hat\u00e1sa most \u00e9rezhet\u0151."},{"id":24,"category":"passive","english":"The documents <b>need to be signed<\/b> before Friday.","hungarian":"A dokumentumokat p\u00e9ntek el\u0151tt al\u00e1 kell \u00edrni.","explanation":"<b>need to be + past participle<\/b> \u2014 sz\u00fcks\u00e9gess\u00e9g kifejez\u00e9se passz\u00edvban."},{"id":25,"category":"wish_if_only","english":"I <b>wish I had known<\/b> about this sooner.","hungarian":"B\u00e1rcsak kor\u00e1bban tudtam volna err\u0151l.","explanation":"<b>wish + past perfect<\/b> \u2014 m\u00faltbeli b\u00e1nk\u00f3d\u00e1s valami miatt, amit nem lehet megv\u00e1ltoztatni."},{"id":26,"category":"wish_if_only","english":"<b>If only<\/b> I <b>had listened<\/b> to my parents.","hungarian":"B\u00e1rcsak hallgattam volna a sz\u00fcleimre.","explanation":"<b>if only + past perfect<\/b> \u2014 er\u0151s sajn\u00e1lat a m\u00falt miatt."},{"id":27,"category":"wish_if_only","english":"I <b>wish<\/b> it <b>would stop<\/b> raining.","hungarian":"B\u00e1rcsak abbahagyna az es\u0151.","explanation":"<b>wish + would + infinitive<\/b> \u2014 jelenbeli bosszankod\u00e1s, amit nem tudunk befoly\u00e1solni."},{"id":28,"category":"used_to","english":"He <b>used to live<\/b> near the river.","hungarian":"R\u00e9gebben a foly\u00f3 k\u00f6zel\u00e9ben lakott.","explanation":"<b>used to + infinitive<\/b> \u2014 m\u00faltban rendszeres cselekv\u00e9s vagy \u00e1llapot, ami m\u00e1r nem \u00e1ll fenn."},{"id":29,"category":"used_to","english":"We <b>used to spend<\/b> every summer at the lake.","hungarian":"Minden nyarat a t\u00f3n\u00e1l t\u00f6lt\u00f6tt\u00fcnk valamikor.","explanation":"<b>used to + infinitive<\/b> \u2014 m\u00faltbeli szok\u00e1s, ami m\u00e1ra megsz\u0171nt."},{"id":30,"category":"used_to","english":"She <b>didn't use to like<\/b> vegetables, but now she loves them.","hungarian":"R\u00e9gebben nem szerette a z\u00f6lds\u00e9geket, de most im\u00e1dja \u0151ket.","explanation":"<b>didn't use to + infinitive<\/b> \u2014 m\u00faltbeli szok\u00e1s tagad\u00e1sa."},{"id":31,"category":"conditional","english":"<b>If<\/b> it <b>rains<\/b> tomorrow, we <b>will cancel<\/b> the trip.","hungarian":"Ha holnap esik az es\u0151, lemondj\u00e1k a kir\u00e1ndul\u00e1st.","explanation":"<b>1. felt\u00e9teles<\/b> \u2014 re\u00e1lis j\u00f6v\u0151beli lehet\u0151s\u00e9g: if + jelen, will + infinitive."},{"id":32,"category":"conditional","english":"<b>If<\/b> I <b>were<\/b> you, I <b>would apologize<\/b>.","hungarian":"Ha a te helyedben lenn\u00e9k, bocs\u00e1natot k\u00e9rn\u00e9k.","explanation":"<b>2. felt\u00e9teles<\/b> \u2014 hipotetikus jelenbeli helyzet: if + past simple, would + infinitive."},{"id":33,"category":"conditional","english":"<b>If<\/b> she <b>had studied<\/b> harder, she <b>would have passed<\/b>.","hungarian":"Ha jobban tanult volna, \u00e1tment volna.","explanation":"<b>3. felt\u00e9teles<\/b> \u2014 m\u00faltbeli hipotetikus helyzet: if + past perfect, would have + past participle."},{"id":34,"category":"conditional","english":"<b>If<\/b> water <b>reaches<\/b> 100\u00b0C, it <b>boils<\/b>.","hungarian":"Ha a v\u00edz el\u00e9ri a 100 fokot, felforr.","explanation":"<b>0. felt\u00e9teles<\/b> \u2014 \u00e1ltal\u00e1nos igazs\u00e1g vagy t\u00f6rv\u00e9nyszer\u0171s\u00e9g: if + jelen, jelen."},{"id":35,"category":"reported_speech","english":"She said she <b>was working<\/b> on a new project.","hungarian":"Azt mondta, hogy egy \u00faj projekten dolgozik.","explanation":"<b>Reported speech<\/b> \u2014 az id\u00e9zett mondatban az igeid\u0151 eggyel visszal\u00e9p (present \u2192 past continuous)."},{"id":36,"category":"reported_speech","english":"He told me he <b>had already finished<\/b> the report.","hungarian":"Azt mondta nekem, hogy m\u00e1r befejezte a jelent\u00e9st.","explanation":"<b>Reported speech<\/b> \u2014 past simple \u2192 past perfect a f\u00fcgg\u0151 besz\u00e9dben."},{"id":37,"category":"reported_speech","english":"They asked whether I <b>would be able to<\/b> come.","hungarian":"Megk\u00e9rdezt\u00e9k, hogy tudok-e majd j\u00f6nni.","explanation":"<b>Reported speech k\u00e9rd\u00e9s<\/b> \u2014 will \u2192 would; a sz\u00f3rend kijelent\u0151 mondat lesz (nem k\u00e9rd\u0151)."},{"id":38,"category":"phrasal_verbs","english":"She decided to <b>give up<\/b> smoking after the diagnosis.","hungarian":"A diagn\u00f3zis ut\u00e1n \u00fagy d\u00f6nt\u00f6tt, felhagy a doh\u00e1nyz\u00e1ssal.","explanation":"<b>give up<\/b> \u2014 abbahag, lemond valamir\u0151l. Elv\u00e1laszthatatlan (inseparable) phrasal verb."},{"id":39,"category":"phrasal_verbs","english":"I'm really <b>looking forward to<\/b> the weekend.","hungarian":"Nagyon v\u00e1rom m\u00e1r a h\u00e9tv\u00e9g\u00e9t.","explanation":"<b>look forward to<\/b> \u2014 \u00f6r\u00f6mmel v\u00e1r valamit. A \"to\" ut\u00e1n gerund (-ing) j\u00f6n, nem infinitive!"},{"id":40,"category":"phrasal_verbs","english":"Don't <b>put off<\/b> until tomorrow what you can do today.","hungarian":"Ne halaszd holnapra, amit ma megtehetsz.","explanation":"<b>put off<\/b> \u2014 elhalaszt, elod\u00e1z. Elv\u00e1laszthat\u00f3 (separable): put it off."},{"id":41,"category":"phrasal_verbs","english":"How are you <b>getting on<\/b> with your new colleagues?","hungarian":"Hogyan boldogulsz az \u00faj koll\u00e9g\u00e1iddal?","explanation":"<b>get on (with)<\/b> \u2014 kij\u00f6n valakivel, boldogul valamivel. Brit angol kifejez\u00e9s."},{"id":42,"category":"phrasal_verbs","english":"They finally <b>came up with<\/b> a solution.","hungarian":"V\u00e9g\u00fcl tal\u00e1ltak egy megold\u00e1st.","explanation":"<b>come up with<\/b> \u2014 kital\u00e1l, el\u0151\u00e1ll valamivel. Nem elv\u00e1laszthat\u00f3."},{"id":43,"category":"false_friends","english":"The meeting was postponed for <b>actual<\/b> reasons \u2014 not because of politics.","hungarian":"\"Actual\" = val\u00f3s, t\u00e9nyleges \u2014 NEM \"aktu\u00e1lis\" (jelenlegi)! Az \"aktu\u00e1lis\" angolul: current \/ present \/ relevant.","explanation":"<b>actual \u2260 aktu\u00e1lis<\/b> \u2014 tipikus csapda. \"Actual\" = real, genuine. \"Current\" a helyes ford\u00edt\u00e1sa az \"aktu\u00e1lisnak\"."},{"id":44,"category":"false_friends","english":"<b>Eventually<\/b> he admitted he was wrong.","hungarian":"\"Eventually\" = v\u00e9g\u00fcl, v\u00e9geredm\u00e9nyben \u2014 NEM \"eventu\u00e1lisan\" (esetlegesen)!","explanation":"<b>eventually \u2260 eventu\u00e1lisan<\/b> \u2014 eventually = in the end, finally. \"Esetlegesen\" angolul: possibly \/ perhaps."},{"id":45,"category":"false_friends","english":"The <b>sympathetic<\/b> nurse listened patiently to every patient.","hungarian":"\"Sympathetic\" = meg\u00e9rt\u0151, egy\u00fctt\u00e9rz\u0151 \u2014 NEM \"szimpatikus\" (likeable)!","explanation":"<b>sympathetic \u2260 szimpatikus<\/b> \u2014 sympathetic = showing sympathy\/understanding. \"Szimpatikus\" angolul: likeable \/ nice \/ pleasant."},{"id":46,"category":"prepositions","english":"The success of the project depends <b>on<\/b> everyone's cooperation.","hungarian":"A projekt sikere mindenki egy\u00fcttm\u0171k\u00f6d\u00e9s\u00e9t\u0151l f\u00fcgg.","explanation":"<b>depend on<\/b> \u2014 f\u00fcgg valamit\u0151l. Fontos: \"depend ON\", nem \"depend from\"."},{"id":47,"category":"prepositions","english":"She's very good <b>at<\/b> solving complex problems.","hungarian":"Nagyon j\u00f3 \u00f6sszetett probl\u00e9m\u00e1k megold\u00e1s\u00e1ban.","explanation":"<b>good at<\/b> \u2014 j\u00f3 valamiben. Az \"at\" ut\u00e1n gerund (-ing) vagy f\u0151n\u00e9v j\u00f6n."},{"id":48,"category":"prepositions","english":"He's been interested <b>in<\/b> astronomy since childhood.","hungarian":"Gyerekkora \u00f3ta \u00e9rdekli a csillag\u00e1szat.","explanation":"<b>interested in<\/b> \u2014 \u00e9rdekli valami. Fontos: \"in\", nem \"for\" vagy \"about\"."},{"id":49,"category":"prepositions","english":"I'm really proud <b>of<\/b> what you've achieved.","hungarian":"Nagyon b\u00fcszke vagyok arra, amit el\u00e9rt\u00e9l.","explanation":"<b>proud of<\/b> \u2014 b\u00fcszke valamire. Angolul \"of\", nem \"from\" vagy \"about\"."}],"categories":["conditional","could_have","false_friends","have_been","might_have","must_have","passive","phrasal_verbs","prepositions","reported_speech","should_have","used_to","wish_if_only","would_have"],"activeCategory":"all"},"url":"\/sentence-trainer","version":"8f4ca32974876a648b2aa33abd3f4aea","sharedProps":["errors","name","auth","sidebarOpen","flash"]}</script><div id="app"></div>